const activities=base.map(([id,city,title,category,place,metro,cost,hours,image,indoor,max,tags,description,time])=>({id,city,title,category,place,metro,cost,hours,image:id.endsWith('-music')?'music':id.endsWith('-reading')?'books':id.endsWith('-market')?'street':image,indoor,max,tags,description,time}));
const find=id=>activities.find(a=>a.id===id);
const defaults={city:'上海',day:'sat',weather:'sun',budget:150,people:2,category:'全部',query:'',sort:'match'};
let saved={prefs:{...defaults},favorites:[],plan:[],checks:[],guides:[],trips:[]};
try{const raw=JSON.parse(localStorage.getItem('chumenma-v1')||'null');if(raw&&typeof raw==='object'){for(const key of ['favorites','plan','checks','guides','trips'])if(Array.isArray(raw[key]))saved[key]=raw[key];saved.prefs={...defaults,...raw.prefs};}}catch{}
saved.plan=saved.plan.filter(id=>find(id));saved.favorites=saved.favorites.filter(id=>find(id));
let state={...saved.prefs,tab:'explore',recordTab:'checks'};
if(!['上海','杭州','成都'].includes(state.city))state.city='上海';if(!['sun','rain','heat'].includes(state.weather))state.weather='sun';
let activeShare=null;let toastTimer;const $=s=>document.querySelector(s);
function persist(){saved.prefs=Object.fromEntries(Object.keys(defaults).map(k=>[k,state[k]]));try{localStorage.setItem('chumenma-v1',JSON.stringify(saved));return true;}catch{toast('浏览器存储不可用，本次更改只会保留到页面关闭。');return false;}}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function weekend(){const today=new Date();const day=today.getDay();const sat=new Date(today);sat.setDate(today.getDate()+(day===0?-1:(6-day+7)%7));const sun=new Date(sat);sun.setDate(sat.getDate()+1);return {sat,sun};}
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const short=d=>`${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}`;
const selectedDate=()=>iso(weekend()[state.day]);
const total=()=>saved.plan.reduce((s,id)=>s+(find(id)?.cost||0),0);
const options=(items,value)=>items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('');
function rank(a){return 30+(state.weather==='sun'?(!a.indoor?25:15):(a.indoor?40:0))+(a.cost<=state.budget/2?10:0)+(state.people<=a.max?15:0)+(state.people===1&&a.max===2?15:0);}
function recommended(){let list=activities.filter(a=>a.city===state.city&&a.cost<=state.budget&&(state.category==='全部'||a.category===state.category)&&`${a.title}${a.place}${a.tags.join('')}${a.category}`.includes(state.query.trim()));return list.sort((a,b)=>state.sort==='price'?a.cost-b.cost:state.sort==='duration'?a.hours-b.hours:rank(b)-rank(a));}
function reason(a){if(state.people>a.max)return `建议 ${a.max} 人以内；当前同行 ${state.people} 人`;if(state.weather==='rain')return a.indoor?'室内安排，适合当前雨天情景':'户外路线，雨天建议换一天';if(state.weather==='heat')return a.indoor?'室内安排，避开午后高温':'户外路线，建议清晨或傍晚';return a.cost===0?`无需门票 · 预留 ${a.hours} 小时`:a.indoor?`室内慢逛 · 适合 1–${a.max} 人`:`晴天适合出发 · 约 ${a.hours} 小时`;}
function card(a,i=0,variant='standard'){
 const chosen=saved.plan.includes(a.id),favorite=saved.favorites.includes(a.id);
 return `<article class="activity ${variant}" style="--item:${i}">
 <div class="photo-wrap"><button class="photo" data-detail="${a.id}" aria-label="查看${esc(a.title)}"><img src="${images[a.image]}" alt="${imageAlt(a.image)}" width="900" height="700" ${i>2?'loading="lazy"':''}><span class="photo-open" aria-hidden="true">查看路线 ↗</span></button><span class="photo-index">${String(i+1).padStart(2,'0')}</span><button class="save-btn ${favorite?'saved':''}" data-action="favorite" data-id="${a.id}" aria-label="${favorite?'取消收藏':'收藏'}${esc(a.title)}" aria-pressed="${favorite}">${icon('heart')}</button></div>
 <div class="card-body"><div class="card-category"><span>${categoryLabel(a.category)}</span><span>${a.indoor?'室内':'户外'} / ${a.hours}h</span></div><h3><button class="card-title" data-detail="${a.id}">${a.title}</button></h3><p class="card-info">${a.place}</p><p class="card-description">${a.description.split('。')[0]}。</p><div class="match-reason">${reason(a)}</div><div class="card-bottom"><div class="price">${a.cost===0?'免费':`<small>约</small> ¥${a.cost}`}<small> / 人</small></div><button class="add-btn ${chosen?'selected':''}" data-action="toggle-plan" data-id="${a.id}" aria-pressed="${chosen}">${icon(chosen?'check':'plus')}${chosen?'已加入':'加入周末'}</button></div></div></article>`;
}
function filterMarkup(){
 return `<section class="filters" aria-label="推荐偏好"><div class="filter-top"><label class="field-line"><span>城市</span><select id="city" aria-label="探索城市">${options(['上海','杭州','成都'],state.city)}</select></label><label class="field-line"><span>出发</span><select id="day" aria-label="出发日期">${options([['sat',`周六 ${short(weekend().sat)}`],['sun',`周日 ${short(weekend().sun)}`]],state.day)}</select></label><label class="field-line"><span>天气情景</span><select id="weather" aria-label="天气情景">${options([['sun','晴天'],['rain','雨天 · 室内优先'],['heat','高温 · 室内优先']],state.weather)}</select></label><label class="search-box">${icon('search')}<input id="query" aria-label="搜索活动或地点" placeholder="搜索街区、活动、关键词" value="${esc(state.query)}" maxlength="60"></label><button class="search-submit" data-action="recommend" aria-label="搜索活动">${icon('arrow')}</button></div><div class="filter-bottom"><label class="budget-field"><span>人均预算</span><input id="budget" type="range" min="0" max="300" step="10" value="${state.budget}" aria-label="人均预算"><output id="budget-value">¥${state.budget}</output></label><label class="people-field"><span>同行</span><select id="people" aria-label="同行人数">${options([[1,'1 人'],[2,'2 人'],[3,'3 人'],[4,'4 人'],[6,'6 人']],Number(state.people))}</select></label><span class="filter-note">活动费用估算 · 不含交通餐饮</span><button class="text-btn" data-action="reset">重置筛选</button></div></section>`;
}
function sidebar(){
 const weather={sun:['22–27°','晴天情景','适合步行。带水，做好防晒。'],rain:['19–23°','雨天情景','室内优先；户外路线可留作备选。'],heat:['30–35°','高温情景','避开午后暴晒，预留室内休息点。']}[state.weather];
 return `<aside class="sidebar"><section class="weather-card"><div class="weather-top"><span>${state.city} / ${state.day==='sat'?'周六':'周日'}</span><span>WEATHER</span></div><div class="weather-main"><b>${weather[0]}</b>${icon(state.weather)}</div><p>${weather[1]} · ${weather[2]}</p><span class="scenario">情景演示，非实时预报</span></section><section class="plan-card" id="weekend-plan"><div class="plan-heading"><div><span class="eyebrow">YOUR ITINERARY</span><h2>周末出行单</h2></div><span class="plan-count">${String(saved.plan.length).padStart(2,'0')}</span></div>${saved.plan.length?`<ol class="plan-list">${saved.plan.map((id,i)=>{const a=find(id);return `<li class="plan-item"><span class="plan-number">${String(i+1).padStart(2,'0')}</span><div><strong>${a.title}</strong><small>${a.city} · ${a.hours}h · 约 ¥${a.cost}</small></div><button class="remove-btn" data-action="toggle-plan" data-id="${id}" aria-label="移除${a.title}">×</button></li>`;}).join('')}</ol>`:`<div class="plan-empty"><span>01 —</span><p>从一个想去的地方开始。</p><small>点击活动上的「加入周末」</small></div>`}<div class="plan-summary"><span>预计人均</span><strong>¥${total()}</strong></div><p class="caption">不含交通与餐饮${saved.plan.length?` · 活动约 ${saved.plan.reduce((s,id)=>s+find(id).hours,0)}h`:''}</p>${total()>state.budget?`<div class="warning">超出预算 ¥${total()-state.budget}，可移除活动调整。</div>`:''}${saved.plan.reduce((s,id)=>s+find(id).hours,0)>6?'<div class="warning">活动超过 6 小时，建议分两天安排，并留出交通时间。</div>':''}<button class="btn btn-primary full" data-action="trip">约朋友出发 ${icon('arrow')}</button><button class="plan-link" data-action="view-plan">查看完整出行单</button></section></aside>`;
}
function explore(){
 const list=recommended(),categories=[['全部','全部','INDEX'],['看展','看展','ART'],['去户外','漫步','OUTDOORS'],['听现场','现场','LIVE'],['逛市集','市集','STREETS']];
 return `<div class="issue-line"><span>城市探索手册 / ${state.city}</span><span>${short(weekend().sat)} — ${short(weekend().sun)} · 本周末</span></div><section class="masthead"><h1>周末，<em>在城里。</em></h1><p>选一处去处，留半日空白。<br>看展、散步，或者听一场现场。</p></section><nav class="category-index" aria-label="活动分类">${categories.map(([key,label,en],i)=>`<button class="category-entry ${state.category===key?'active':''}" data-category="${key}" aria-pressed="${state.category===key}"><span class="category-no">0${i}</span><span class="category-word">${label}</span><span class="category-en">${en}</span></button>`).join('')}</nav>${filterMarkup()}<div class="content-grid"><section class="results" aria-label="活动推荐"><div class="section-head"><h2>${state.category==='全部'?'本周去处':categoryLabel(state.category)}<span class="counter">${String(list.length).padStart(2,'0')}</span></h2><div class="section-tools"><span class="caption desktop">路线灵感 · 示例</span><select id="sort" aria-label="推荐排序">${options([['match','按偏好推荐'],['price','预算从低到高'],['duration','时长从短到长']],state.sort)}</select></div></div>${list.length?`<div class="editorial-feature" id="activity-grid">${card(list[0],0,'lead')}<div class="side-stack">${list.slice(1,3).map((a,i)=>card(a,i+1,'compact')).join('')}</div></div>${list.length>3?`<div class="more-heading"><span>继续翻阅</span><span>MORE TO EXPLORE</span></div><div class="activity-grid">${list.slice(3).map((a,i)=>card(a,i+3)).join('')}</div>`:''}`:empty('暂时没有合适的去处','试试增加预算、清空关键词，或换一种兴趣。','重置筛选','reset')}<div class="summary-strip"><div><span class="eyebrow">A LITTLE SERENDIPITY</span><p>还没想好去哪？</p></div><button class="text-btn" data-action="surprise" ${!list.length?'disabled':''}>随机翻开一页 ${icon('arrow')}</button></div></section>${sidebar()}</div><div class="mobile-plan"><span><b>${saved.plan.length}</b> 个去处 · 人均 ¥${total()}</span><button data-action="${saved.plan.length?'view-plan':'focus-plan'}">出行单 ${icon('arrow')}</button></div>`;
}
function empty(title,text,button,action){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${text}</p><button class="btn btn-primary" data-action="${action}">${button}</button></div>`;}
const sampleGuides=[{id:'g1',title:'50 元以内，过一个不赶路的周末',category:'小预算 · 大满足',image:'city',intro:'把路线缩短一点，把停留的时间拉长一点。快乐不一定需要门票。',content:'先选一个免费的城市散步点，再留 20–30 元给一杯饮品或一份小吃。\n\n建议节奏：下午出发 → 步行 1 小时 → 坐下来休息 → 等一场日落。\n\n把往返交通单独算进预算，避开需要额外消费的项目。真正值得记住的，往往是途中随手发现的小事。\n\n本文为通用攻略示例，费用为规划参考。'}, {id:'g2',title:'下雨了？刚好去看一场展',category:'雨天备选 · 室内充电',image:'art',intro:'一双舒服的鞋，一把伞，一下午的好奇心。雨天也可以很有意思。',content:'先在馆方官方渠道看清展期、闭馆日和预约要求，学生票别忘带证件。\n\n不必一次看完整个展馆。挑最感兴趣的一个展区，给每件喜欢的作品多留一点时间。\n\n和朋友同行时可以先各自看，再约定一个时间交换最喜欢的作品。附近找个室内休息点作为备选，少走雨中的冤枉路。\n\n配图为展览类型示意，不对应实时展讯。'}, {id:'g3',title:'第一次轻徒步，带这些就够了',category:'户外入门 · 轻装出发',image:'nature',intro:'从城市附近的 3–5 公里开始，不比速度，只收集沿途的绿色。',content:'选一条正规、已开放且交通方便的低强度步道，提前了解返程时间。\n\n小背包里放饮水、少量食物、充电宝、纸巾和防晒用品。穿舒适防滑的鞋，不为拍照偏离步道。\n\n查看最新天气。强降雨、高温或雷电预警时取消户外计划，改成室内活动。结伴出发，约定集合点和返程时间。\n\n本文是通用规划建议，具体路况以当地最新公告为准。'}];
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="page-description">${desc}</p></div>${action}</div>`;}
function teams(){
 const examples=activities.filter(a=>a.city===state.city).slice(0,3);
 return `${heading('02 / GO TOGETHER','约一个人，一起出门。','把去处、时间和集合点整理好，发给想约的朋友。',`<button class="btn btn-primary" data-action="trip">发起组队 ${icon('plus')}</button>`)}<div class="notice">${icon('info')} 邀请可通过链接打开。计划保存在本机，报名及成员状态不会自动同步。</div><div class="section-head"><h2>${state.city} · 组队灵感 <span class="counter">03</span></h2><button class="text-btn" data-tab="explore">更换城市 ↗</button></div><div class="team-grid">${examples.map((a,i)=>`<article class="team-card"><button class="team-photo" data-detail="${a.id}" aria-label="查看${a.title}"><img src="${images[a.image]}" alt="${imageAlt(a.image)}" width="700" height="500"><span>0${i+1} / ${categoryLabel(a.category)}</span></button><div class="team-content"><span class="eyebrow">路线灵感 · 示例</span><h3>${['沿江走一段','约一场展览','去林间散步'][i]}</h3><div class="team-meta"><p>${a.title}</p><p>${selectedDate()} · ${i===2?'09:30':'14:00'}</p><p>计划 ${i===1?'2–4':'2–6'} 人 · 约 ¥${a.cost}/人</p></div><button class="btn full" data-action="team-example" data-id="${a.id}">用这条路线约朋友 ${icon('arrow')}</button></div></article>`).join('')}</div>${saved.trips.length?`<div class="section-head"><h2>保存的组队计划</h2></div><div class="record-list">${saved.trips.map(t=>`<article class="record"><div class="record-head"><h3>${esc(t.title)}</h3><span>${esc(t.date)}</span></div><p>${esc(t.city)} · ${esc(t.people)} 人 · ${esc(t.meeting)}</p><button class="text-btn" data-action="open-trip" data-id="${esc(t.id)}">查看与分享 ↗</button></article>`).join('')}</div>`:''}`;
}
function guides(){
 return `${heading('03 / FIELD NOTES','城市，值得再读一遍。','出发前的路线参考，回来后的经验笔记。',`<button class="btn btn-primary" data-action="write-guide">写攻略 ${icon('plus')}</button>`)}<div class="guide-grid">${sampleGuides.map((g,i)=>`<article class="guide-card"><button class="guide-photo" data-action="read-guide" data-id="${g.id}" aria-label="阅读${g.title}"><img src="${images[g.image]}" width="1000" height="700" alt="${imageAlt(g.image)}"><span>READ STORY ↗</span></button><div class="guide-content"><p class="eyebrow">0${i+1} / ${g.category}</p><h2><button class="card-title" data-action="read-guide" data-id="${g.id}">${g.title}</button></h2><p>${g.intro}</p><div class="guide-author"><span>出门吗编辑部 · 示例攻略</span><button class="text-btn" data-action="read-guide" data-id="${g.id}">阅读全文 ↗</button></div></div></article>`).join('')}</div>${saved.guides.length?`<div class="section-head"><h2>我写的攻略</h2></div><div class="record-list">${saved.guides.map(g=>`<article class="record"><h3>${esc(g.title)}</h3><p>${esc(g.content.slice(0,100))}${g.content.length>100?'…':''}</p><button class="text-btn" data-action="read-guide" data-id="${esc(g.id)}">查看与分享 ↗</button></article>`).join('')}</div>`:''}<div class="notice">${icon('book')} 攻略保存在当前浏览器。分享链接包含文章内容，朋友无需登录即可阅读。</div>`;
}
function records(){
 let inner='';
 if(state.recordTab==='checks')inner=saved.checks.length?saved.checks.map((c,i)=>{const a=find(c.activity);return `<article class="record check-record">${a?`<img src="${images[a.image]}" width="240" height="180" alt="${imageAlt(a.image)}">`:''}<div><div class="record-head"><span class="eyebrow">${esc(c.date)} / ${'★'.repeat(c.rating)}</span><span class="record-number">${String(i+1).padStart(2,'0')}</span></div><h3>${esc(a?.title||c.title)}</h3><p>${esc(c.note||'这次出发，已经记下。')}</p><div class="inline-actions"><button class="text-btn" data-action="check-guide" data-id="${esc(c.id)}">写成攻略 ↗</button><button class="text-btn muted" data-action="delete-check" data-id="${esc(c.id)}">撤销打卡</button></div></div></article>`;}).join(''):empty('第一页，等你出发。','在活动详情里打卡，记下日期、花费和体验。','看看本周去处','explore');
 else if(state.recordTab==='favorites')inner=saved.favorites.length?saved.favorites.map((id,i)=>card(find(id),i)).join(''):empty('把想去的地方，留在这里。','收藏活动，下次安排周末时就能找到。','探索周末','explore');
 else inner=saved.guides.length?saved.guides.map(g=>`<article class="record"><span class="eyebrow">${esc(g.date)}</span><h3>${esc(g.title)}</h3><p>${esc(g.content.slice(0,120))}</p><button class="text-btn" data-action="read-guide" data-id="${esc(g.id)}">阅读与分享 ↗</button></article>`).join(''):empty('写一份自己的城市笔记。','记录路线、实际花费和建议，留给下一次出发。','写第一篇攻略','write-guide');
 return `${heading('04 / PERSONAL ARCHIVE','去过的地方，留下的日子。','你的收藏、打卡与城市笔记。')}<div class="stats-row"><div class="stat"><b>${String(saved.checks.length).padStart(2,'0')}</b><span>次打卡</span></div><div class="stat"><b>${String(saved.favorites.length).padStart(2,'0')}</b><span>个收藏</span></div><div class="stat"><b>${String(saved.guides.length).padStart(2,'0')}</b><span>篇攻略</span></div></div><div class="record-tabs">${[['checks','打卡记录'],['favorites','我的收藏'],['guides','我的攻略']].map(([k,t])=>`<button class="${state.recordTab===k?'active':''}" data-record-tab="${k}" aria-pressed="${state.recordTab===k}">${t}</button>`).join('')}</div><div class="${state.recordTab==='favorites'?'activity-grid':'record-list'}">${inner}</div><div class="notice">${icon('info')} 记录仅保存在当前浏览器，清除浏览器数据后会丢失。攻略可生成分享链接保存。</div>`;
}

const categoryLabel=c=>({'去户外':'漫步','听现场':'现场','逛市集':'市集','看展':'看展'}[c]||c);
const imageAlt=k=>({city:'上海城市风景，路线类别示意',art:'展览空间，类别示意',nature:'林间步道，类别示意',music:'音乐现场观众，类别示意',books:'书店书架，类别示意',street:'城市街区，类别示意'}[k]||'活动类别示意图');
const reducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const rectTransform=(from,to)=>'translate('+(from.left-to.left)+'px,'+(from.top-to.top)+'px) scale('+(from.width/to.width)+','+(from.height/to.height)+')';
let dialogOrigin=null,dialogReturnFocus=null,photoTransition=null;
async function animatePhoto(hero,from,to,duration){
 const ghost=hero.cloneNode();ghost.removeAttribute('class');ghost.removeAttribute('id');ghost.alt='';ghost.setAttribute('aria-hidden','true');
 Object.assign(ghost.style,{position:'fixed',left:to.left+'px',top:to.top+'px',width:to.width+'px',height:to.height+'px',maxWidth:'none',margin:0,objectFit:'cover',transformOrigin:'0 0',zIndex:5,pointerEvents:'none'});
 $('#dialog').append(ghost);hero.style.visibility='hidden';
 const animation=ghost.animate([{transform:rectTransform(from,to)},{transform:'none'}],{duration,easing:'cubic-bezier(.2,.75,.25,1)',fill:'both'});
 photoTransition={animation,ghost,hero};
 try{await animation.finished;}catch{}finally{ghost.remove();hero.style.visibility='';if(photoTransition?.ghost===ghost)photoTransition=null;}
}
async function closeDialog(){
 const dialog=$('#dialog');if(!dialog.open||dialog.classList.contains('is-closing'))return;
 photoTransition?.animation.cancel();dialog.classList.add('is-closing');const hero=$('.dialog-photo');
 const target=dialogOrigin&&(dialogOrigin.element.isConnected?dialogOrigin.element:document.querySelector('[data-detail="'+dialogOrigin.id+'"] img'));
 if(hero&&target&&!reducedMotion()){
  const from=hero.getBoundingClientRect(),to=target.getBoundingClientRect();
  if(to.bottom>0&&to.top<innerHeight)await animatePhoto(hero,from,to,240);
 }
 dialog.close();
}
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#dialog').addEventListener('close',()=>{
 document.body.classList.remove('modal-open');$('#dialog').classList.remove('is-closing');
 const fallback=dialogOrigin&&document.querySelector('[data-detail="'+dialogOrigin.id+'"]');
 const focus=dialogReturnFocus?.isConnected?dialogReturnFocus:fallback;
 (focus||$('#app')).focus({preventScroll:true});dialogOrigin=null;
});

function render(){
 const active=$('#app').contains(document.activeElement)?document.activeElement:null;
 let focusSelector='';
 if(active?.id)focusSelector='#'+CSS.escape(active.id);
 else if(active?.dataset.category)focusSelector='[data-category="'+CSS.escape(active.dataset.category)+'"]';
 else if(active?.dataset.recordTab)focusSelector='[data-record-tab="'+CSS.escape(active.dataset.recordTab)+'"]';
 else if(active?.dataset.action&&active.dataset.id)focusSelector='[data-action="'+CSS.escape(active.dataset.action)+'"][data-id="'+CSS.escape(active.dataset.id)+'"]';
 document.querySelectorAll('.nav-item').forEach(el=>{el.classList.toggle('active',el.dataset.tab===state.tab);el.setAttribute('aria-current',el.dataset.tab===state.tab?'page':'false');});
 $('#app').innerHTML=({explore,teams,guides,records}[state.tab]||explore)();
 if(focusSelector)$('#app').querySelector(focusSelector)?.focus({preventScroll:true});
}
function modal(html){
 photoTransition?.animation.cancel();const dialog=$('#dialog');dialog.classList.remove('detail-mode');dialog.classList.remove('is-closing');dialogOrigin=null;
 $('#dialog-body').innerHTML=html;if(!dialog.open){dialogReturnFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open');}else{$('.dialog-close').focus({preventScroll:true});}dialog.scrollTop=0;
}
function detail(id,source){
 const a=find(id);if(!a)return;
 const wasOpen=$('#dialog').open;
 const origin=source?.closest('.activity,.team-card')?.querySelector('img')||document.querySelector('.photo[data-detail="'+id+'"] img');
 const from=origin?.getBoundingClientRect();
 modal(`<div class="detail-layout"><div class="detail-image"><img class="dialog-photo" src="${images[a.image]}" alt="${imageAlt(a.image)}"><span>${a.city} / ${categoryLabel(a.category)}</span></div><div class="detail-content"><div class="dialog-eyebrow">${a.city} / ${categoryLabel(a.category)} / 示例路线</div><h2 id="dialog-title" class="dialog-title">${a.title}</h2><p class="dialog-description">${a.description}</p><div class="detail-grid"><span>${icon('pin')}${a.place}</span><span>${icon('clock')}约 ${a.hours} 小时</span><span>${icon('people')}适合 1–${a.max} 人</span><span>${icon('bag')}约 ¥${a.cost}/人</span></div><p class="dialog-description">${a.time}<br>${a.metro}</p><div class="notice">${reason(a)}<br>费用不含交通餐饮。开放、展期和票价需出发前核实。</div><div class="dialog-actions"><button class="btn btn-primary" data-action="detail-add" data-id="${a.id}">${icon(saved.plan.includes(id)?'check':'plus')}${saved.plan.includes(id)?'已加入周末':'加入周末出行单'}</button><button class="btn" data-action="checkin" data-id="${a.id}">${icon('camera')}打卡记录</button><a class="text-btn" target="_blank" rel="noopener noreferrer" href="https://uri.amap.com/search?keyword=${encodeURIComponent(a.place)}&city=${encodeURIComponent(a.city)}&view=map">地图查看 ↗</a></div><p class="caption">图片：<a href="${credits[a.image][1]}" target="_blank" rel="noopener noreferrer">${credits[a.image][0]} / Unsplash</a><br>类别示意，非具体路线或场所实拍</p></div></div>`);
 $('#dialog').classList.add('detail-mode');
 if(origin&&from){dialogOrigin={id,element:origin};if(!wasOpen&&!reducedMotion()&&from.bottom>0&&from.top<innerHeight){const to=$('.dialog-photo').getBoundingClientRect();animatePhoto($('.dialog-photo'),from,to,380);$('.detail-content').animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'none'}],{duration:280,delay:90,fill:'backwards'});}}
}
function togglePlan(id){if(saved.plan.includes(id)){saved.plan=saved.plan.filter(x=>x!==id);persist();render();return;}if(saved.plan.length>=6){toast('一份出行单最多放 6 个活动，留点时间慢慢逛。');return;}if(saved.plan.length&&find(saved.plan[0]).city!==find(id).city){toast('一份出行单只安排一座城市，请先移除原城市活动。');return;}saved.plan.push(id);persist();render();toast('已加入你的周末出行单');}
function planMarkup(ids){return `<ol class="steps">${ids.map((id,i)=>{const a=find(id);return `<li><span class="plan-number">${i+1}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.place)} · ${a.hours} 小时<br>${esc(a.metro)}</p></div><small>¥${a.cost}</small></li>`;}).join('')}</ol>`;}
function viewPlan(){if(!saved.plan.length){toast('先选一个喜欢的活动加入周末吧。');return;}modal(`<div class="dialog-eyebrow">MY WEEKEND PLAN</div><h2 id="dialog-title" class="dialog-title">我的周末出行单</h2><p class="dialog-description">${esc(find(saved.plan[0]).city)} · ${selectedDate()} · ${state.people} 人</p>${planMarkup(saved.plan)}<div class="detail-grid"><span>活动人均约 ¥${total()}</span><span>${state.people} 人合计约 ¥${total()*state.people}</span></div><p class="caption">以上不含交通、餐饮；顺序为加入顺序。请预留接驳时间，可移除活动后重新添加来调整顺序。</p><div class="dialog-actions"><button class="btn btn-primary" data-action="trip">${icon('people')}生成组队邀请</button></div>`);}
function tripForm(){if(!saved.plan.length){toast('先把一个活动加入周末出行单，就能发起组队。');state.tab='explore';render();$('#dialog').close();return;}modal(`<div class="dialog-eyebrow">LET'S GO TOGETHER</div><h2 id="dialog-title" class="dialog-title">约个搭子，一起出发</h2><form id="trip-form"><label class="form-field">计划名称<input name="title" maxlength="40" required value="${esc(find(saved.plan[0]).city)}的周末小探索"></label><div class="form-row"><label class="form-field">出发日期<input name="date" type="date" required value="${selectedDate()}"></label><label class="form-field">集合时间<input name="time" type="time" required value="14:00"></label></div><div class="form-row"><label class="form-field">你的称呼<input name="host" maxlength="20" required placeholder="朋友怎么称呼你"></label><label class="form-field">计划人数<select name="people">${options([[2,'2 人'],[3,'3 人'],[4,'4 人'],[6,'6 人']],state.people===1?2:Number(state.people))}</select></label></div><label class="form-field">集合地点<input name="meeting" maxlength="80" required value="${esc(find(saved.plan[0]).metro)}"></label><label class="form-field">给朋友的话<textarea name="note" maxlength="300" placeholder="比如：不赶路，走累了就找地方坐坐。"></textarea></label><div class="notice">保存后生成邀请链接。朋友可查看路线并联系你确认，成员和报名状态不会自动同步。</div><button class="btn btn-primary full" type="submit">保存计划并生成邀请 ${icon('arrow')}</button></form>`);}
function shareUrl(type,data){return location.origin+location.pathname+'#'+type+'='+encodeURIComponent(JSON.stringify(data));}
function tripView(t,imported=false){activeShare={type:'trip',data:t};modal(`<div class="dialog-eyebrow">${imported?'A WEEKEND INVITATION':'YOUR WEEKEND IS READY'}</div><h2 id="dialog-title" class="dialog-title">${esc(t.title)}</h2><p class="dialog-description">${esc(t.host)} 邀你一起探索 ${esc(t.city)}</p><div class="detail-grid"><span>${icon('calendar')}${esc(t.date)} ${esc(t.time)}</span><span>${icon('people')}计划 ${esc(t.people)} 人</span><span>${icon('pin')}${esc(t.meeting)}</span><span>${icon('bag')}人均约 ¥${t.ids.reduce((s,id)=>s+find(id).cost,0)}</span></div>${planMarkup(t.ids)}${t.note?`<p class="dialog-description">${esc(t.note)}</p>`:''}<div class="notice">这是可分享的计划副本。加入意向请直接联系发起人，报名状态不会同步；费用不含交通餐饮。</div><label class="caption" for="share-url">邀请链接（可复制保存）</label><input id="share-url" class="share-url" readonly value="${esc(shareUrl('trip',t))}"><div class="dialog-actions"><button class="btn btn-primary" data-action="copy-share">${icon('share')}复制邀请链接</button>${imported?'<button class="btn" data-action="import-trip">保存到我的计划</button><button class="btn" data-action="copy-rsvp">复制参加意向</button>':''}</div>`);}
function checkinForm(id){const a=find(id);modal(`<div class="dialog-eyebrow">A LITTLE MOMENT TO KEEP</div><h2 id="dialog-title" class="dialog-title">记下这次出发</h2><p class="sub" style="margin-bottom:23px">${a.title}</p><form id="check-form" data-id="${id}"><div class="form-row"><label class="form-field">探索日期<input type="date" name="date" required max="${iso(new Date())}" value="${iso(new Date())}"></label><label class="form-field">今天的体验<select name="rating">${options([[5,'★★★★★ 太值得了'],[4,'★★★★ 很不错'],[3,'★★★ 还可以'],[2,'★★ 不太合适'],[1,'★ 有点失望']],5)}</select></label></div><label class="form-field">这次的体验<textarea name="note" maxlength="500" placeholder="看到了什么、花了多少钱、有什么想提醒下次的自己…"></textarea></label><button class="btn btn-primary full" type="submit">${icon('camera')}保存打卡</button><p class="caption" style="margin-top:12px">打卡保存在当前浏览器，也可整理成攻略分享。</p></form>`);}
function writeGuide(c){modal(`<div class="dialog-eyebrow">SHARE YOUR LITTLE DISCOVERY</div><h2 id="dialog-title" class="dialog-title">把这个周末，写成攻略</h2><form id="guide-form"><label class="form-field">攻略标题<input name="title" required maxlength="50" placeholder="给你的周末起个名字" value="${c?esc(find(c.activity)?.title+' · 我的体验'):''}"></label><label class="form-field">你的路线与建议<textarea name="content" required minlength="10" maxlength="1600" style="min-height:220px" placeholder="推荐路线 → 交通方式 → 实际花费 → 体验和避坑建议">${c?esc(c.note):''}</textarea></label><p class="caption" style="margin-bottom:18px">10–1600 字；保存到本机，并生成朋友可直接阅读的分享链接。链接中包含全文，请勿填写敏感个人信息。</p><button class="btn btn-primary full" type="submit">保存并生成分享链接 ${icon('arrow')}</button></form>`);}
function readGuide(g,imported=false){activeShare={type:'guide',data:{id:g.id,title:g.title,content:g.content,date:g.date||iso(new Date())}};modal(`${g.image?`<img class="dialog-photo" src="${images[g.image]}" alt="攻略类别配图">`:''}<div class="dialog-eyebrow">${g.category||'MY WEEKEND STORY'}</div><h2 id="dialog-title" class="dialog-title">${esc(g.title)}</h2><p class="dialog-description">${esc(g.content)}</p><input id="share-url" class="share-url" aria-label="攻略分享链接" readonly value="${esc(shareUrl('guide',activeShare.data))}"><div class="dialog-actions"><button class="btn btn-primary" data-action="copy-share">${icon('share')}复制攻略链接</button>${imported?'<button class="btn" data-action="import-guide">保存攻略副本</button>':''}</div>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制，发给朋友就能打开。');return true;}catch{const el=$('#share-url');if(el){el.value=text;el.focus();el.select();toast('请手动复制已选中的内容。');}else{modal(`<h2 id="dialog-title" class="dialog-title">复制这段话发给朋友</h2><textarea id="share-url" class="share-url" rows="5" readonly>${esc(text)}</textarea>`);$('#share-url').select();}return false;}}
function setTab(tab){state.tab=tab;render();window.scrollTo({top:0,behavior:reducedMotion()?'instant':'smooth'});}
document.addEventListener('click',async e=>{const btn=e.target.closest('button,a,[data-detail]');if(!btn)return;if(btn.closest('.brand')){e.preventDefault();setTab('explore');return;}if(btn.dataset.tab){setTab(btn.dataset.tab);return;}if(btn.dataset.category){state.category=btn.dataset.category;persist();render();return;}if(btn.dataset.recordTab){state.recordTab=btn.dataset.recordTab;render();return;}if(btn.dataset.detail&&!btn.dataset.action){detail(btn.dataset.detail,btn);return;}const id=btn.dataset.id;switch(btn.dataset.action){case 'close':closeDialog();break;case 'focus-plan':$('#weekend-plan')?.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'});break;case 'explore':setTab('explore');break;case 'reset':Object.assign(state,defaults);persist();render();break;case 'recommend':state.query=$('#query')?.value||'';persist();render();toast(`为你找到 ${recommended().length} 个周末好去处`);break;case 'surprise':{const list=recommended();if(list.length)detail(list[Math.floor(Math.random()*list.length)].id);break;}case 'favorite':saved.favorites=saved.favorites.includes(id)?saved.favorites.filter(x=>x!==id):[...saved.favorites,id];persist();render();toast(saved.favorites.includes(id)?'已收藏，在「我的足迹」里等你。':'已取消收藏');break;case 'toggle-plan':togglePlan(id);break;case 'detail-add':if(!saved.plan.includes(id))togglePlan(id);detail(id);break;case 'view-plan':viewPlan();break;case 'trip':tripForm();break;case 'team-example':if(saved.plan.length&&find(saved.plan[0]).city!==find(id).city){toast('请先清空其他城市的出行单，再添加这条路线。');break;}if(!saved.plan.includes(id))togglePlan(id);if(saved.plan.includes(id))tripForm();break;case 'open-trip':{const t=saved.trips.find(t=>t.id===id);if(t)tripView(t);break;}case 'checkin':checkinForm(id);break;case 'delete-check':saved.checks=saved.checks.filter(c=>c.id!==id);persist();render();toast('已撤销这次打卡');break;case 'check-guide':writeGuide(saved.checks.find(c=>c.id===id));break;case 'write-guide':writeGuide();break;case 'read-guide':{const g=[...sampleGuides,...saved.guides].find(g=>g.id===id);if(g)readGuide(g);break;}case 'copy-share':if(activeShare)await copy(shareUrl(activeShare.type,activeShare.data));break;case 'import-trip':if(activeShare?.type==='trip'){const t=activeShare.data;if(!saved.trips.some(x=>x.id===t.id))saved.trips.unshift(t);persist();render();toast('已保存计划副本，后续修改互不影响。');}break;case 'copy-rsvp':if(activeShare?.type==='trip'){const t=activeShare.data;await copy(`我想参加「${t.title}」，${t.date} ${t.time} 在${t.meeting}集合。一起出发前再确认一下吧！`);}break;case 'import-guide':if(activeShare?.type==='guide'){if(!saved.guides.some(g=>g.id===activeShare.data.id))saved.guides.unshift({...activeShare.data});persist();render();toast('已保存攻略副本。');}break;}});
document.addEventListener('change',e=>{const id=e.target.id;if(['city','day','weather','budget','people','sort'].includes(id)){state[id]=['budget','people'].includes(id)?Number(e.target.value):e.target.value;persist();render();}});
document.addEventListener('input',e=>{if(e.target.id==='budget')$('#budget-value').textContent='¥'+e.target.value;if(e.target.id==='query'){state.query=e.target.value;persist();}});
document.addEventListener('keydown',e=>{if(e.target.id==='query'&&e.key==='Enter'){state.query=e.target.value;persist();render();}if(e.target.matches('[data-detail][role="button"]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();detail(e.target.dataset.detail);}});
document.addEventListener('submit',e=>{if(!['trip-form','check-form','guide-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const uid=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);if(e.target.id==='trip-form'){if(!data.title.trim()||!data.host.trim()||!data.meeting.trim()){toast('请补全计划名称、称呼和集合地点。');return;}const t={...data,people:Number(data.people),id:uid,city:find(saved.plan[0]).city,ids:[...saved.plan]};saved.trips.unshift(t);persist();render();tripView(t);}else if(e.target.id==='check-form'){saved.checks.unshift({...data,id:uid,activity:e.target.dataset.id,rating:Number(data.rating)});persist();$('#dialog').close();state.tab='records';state.recordTab='checks';render();toast('已保存这次打卡。');}else{if(data.content.trim().length<10||!data.title.trim()){toast('请填写标题，并写下至少 10 个字的体验。');return;}const g={...data,id:uid,date:iso(new Date())};saved.guides.unshift(g);persist();render();readGuide(g);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function loadHash(){if(!location.hash||location.hash==='#')return;try{const p=new URLSearchParams(location.hash.slice(1));if(p.has('trip')){const t=JSON.parse(p.get('trip'));if(typeof t.title!=='string'||t.title.length>100||typeof t.host!=='string'||typeof t.city!=='string'||typeof t.meeting!=='string'||!Array.isArray(t.ids)||!t.ids.length||t.ids.length>6||!t.ids.every(id=>find(id))||new Set(t.ids).size!==t.ids.length||!t.ids.every(id=>find(id).city===t.city)||!Number.isInteger(t.people)||t.people<1||t.people>20||typeof t.date!=='string'||typeof t.time!=='string'||t.note&&typeof t.note!=='string')throw Error('invalid');tripView(t,true);}else if(p.has('guide')){const g=JSON.parse(p.get('guide'));if(typeof g.title!=='string'||typeof g.content!=='string'||g.title.length>100||g.content.length>3000)throw Error('invalid');readGuide(g,true);}}catch{modal(`<h2 id="dialog-title" class="dialog-title">这个分享链接无法读取</h2><p class="dialog-description">链接可能不完整，请让分享者重新生成。你也可以先探索自己的周末。</p><button class="btn btn-primary" data-action="close" style="margin-top:20px">继续探索</button>`);}}
window.addEventListener('hashchange',loadHash);render();loadHash();
